#!/usr/bin/env python3
"""Extract readable text from a claude session JSONL transcript.
Usage: extract.py <file.jsonl> [regex]   -> prints matched messages with context.
"""
import sys, json, re

path = sys.argv[1]
pattern = sys.argv[2] if len(sys.argv) > 2 else None
rx = re.compile(pattern, re.I) if pattern else None

def text_of(msg):
    """Return a readable string for a transcript record."""
    out = []
    m = msg.get('message') or {}
    role = m.get('role') or msg.get('type') or '?'
    content = m.get('content')
    if content is None:
        content = msg.get('content')
    if isinstance(content, str):
        out.append(content)
    elif isinstance(content, list):
        for blk in content:
            if not isinstance(blk, dict):
                out.append(str(blk)); continue
            t = blk.get('type')
            if t == 'text':
                out.append(blk.get('text',''))
            elif t == 'thinking':
                out.append('[THINKING] ' + blk.get('thinking',''))
            elif t == 'tool_use':
                name = blk.get('name','')
                inp = json.dumps(blk.get('input',{}))[:3000]
                out.append(f'[TOOL_USE {name}] {inp}')
            elif t == 'tool_result':
                c = blk.get('content')
                if isinstance(c, list):
                    for cc in c:
                        if isinstance(cc, dict) and cc.get('type')=='text':
                            out.append('[TOOL_RESULT] ' + cc.get('text',''))
                        else:
                            out.append('[TOOL_RESULT] ' + str(cc)[:3000])
                else:
                    out.append('[TOOL_RESULT] ' + str(c))
            else:
                out.append(f'[{t}] ' + json.dumps(blk)[:1000])
    return role, '\n'.join(out)

with open(path, encoding='utf-8', errors='replace') as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except Exception:
            continue
        role, txt = text_of(msg)
        if rx and not rx.search(txt):
            continue
        print(f'\n===== rec#{i} role={role} =====')
        print(txt[:8000])

